/*
 * A188341  Numbers having no 0's and not more than one 1 in their
 *          representation in base 3.
 * https://oeis.org/A188341
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 20, u16 n <= 65, u32 n <= 230, u64 n <= 860,
 *            u128 n <= 1000, big any n
 * Helpers:   pow3
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A188341: Nth number whose base‑3 representation contains no
 * 0's and at most one 1.  The sequence is generated by listing, for each
 * length L≥1, the L numbers 3^L−1−3^i with i=L−1,…,0, followed by 3^L−1. */
#include "../utils/pow3.h"

seq_t a(idx_t n)
{
    if (n == 0) return 0;              /* not defined for n=0 */

    /* Find length L so that the cumulative count up to length L
     * is at least n.  Count for length L is L+1. */
    idx_t L = 1;
    while ((L * (L + 3) / 2) < n)
        ++L;

    /* Number of terms before those of length L */
    idx_t cum_before = (L - 1) * (L + 2) / 2;
    idx_t pos = n - cum_before - 1;      /* 0‑based offset in block of length L */

    seq_t all_twos = pow3(L) - 1;       /* 3^L − 1 */

    if (pos == L) {                    /* the all‑2 number */
        return all_twos;
    } else {                           /* one‑1 number with i = L‑1–pos */
        idx_t i = (L - 1) - pos;
        return all_twos - pow3(i);
    }
}
